const path = require('path');
const CopyPlugin = require('copy-webpack-plugin');

// Old URL → new URL, regenerated by scripts/build-seo-redirects.mjs and committed.
// Append-only: an entry that disappears from the dataset still has to resolve,
// because Google indexed it. See that script's header.
const SEO_REDIRECTS = require('./data/seo/redirects.json');

// The site moved from this host to the apex. It stays attached to the SAME Vercel
// project so the redirect below can resolve host AND path in a single hop — a
// Vercel domain-level redirect would preserve the path and force a second hop
// through the retired /trains/ URL.
const LEGACY_HOST = 'sleeper-train-map.pingwi.com';
const SITE_ORIGIN = 'https://pingwi.com';

// Absolute destinations are what make one-hop possible from the legacy host, but
// they would bounce a dev server straight to production. Only production gets them.
const isProd = process.env.VERCEL_ENV === 'production';
const dest = (pathname) => (isProd ? `${SITE_ORIGIN}${pathname}` : pathname);

// ---------------------------------------------------------------------------
// Serverless bundle tracing.
//
// Vercel's Deployment Storage bills the build output PLUS one function bundle
// per route, for every deployment it retains. The nightly scrape commits to
// main, so the project produces a deployment a day and pays that per-route
// cost again each time.
//
// file-store.mjs reads its datasets as `fs.readFileSync(path.join(DIR, name))`,
// where DIR is a literal and `name` is a runtime argument. @vercel/nft resolves
// the literal, cannot resolve the argument, and so conservatively pulls in the
// WHOLE directory. file-store.mjs is reachable from nearly every API route, so
// all ~24 MB of committed data under public/data/ landed in all ~15 lambdas —
// 370 MB of function bundles per deployment, of which /api/osm-relation's copy
// was 24.6 MB carrying 0.5 MB of code it actually runs.
//
// The fix is to tell the tracer what each route genuinely cannot reach. Note
// the ordering rule in next/dist/build/collect-build-traces.js: includes are
// merged in FIRST and excludes filter the merged set AFTERWARDS. A blanket
// `'*': ['./public/data/**']` would therefore delete the per-route includes
// below and break the routes it was meant to slim. Excludes must be per route.
//
// Keys are matched against the route with picomatch `contains`, so they are
// spelled in full to keep one route's rule from claiming another's.
// ---------------------------------------------------------------------------

// The four heavyweight groups under public/data, by what reads them.
const DATA = {
  published: './public/data/published/**', //  5.0 MB  canonicalize's merged artifact
  gtfsBundle: './public/data/gtfs/**', //  1.7 MB  PKP/RegioJet bundles
  botRaw: './public/data/scraped/backontrack-*.json', // 12.4 MB  raw Back-on-Track
  osmCache: './public/data/scraped/osm-*.json', //  2.3 MB  cached OSM relations
  operatorTrains: './public/data/scraped/*-trains.json', //  2.5 MB  per-source trains
};
const ALL_DATA = Object.values(DATA);
const except = (...keep) => ALL_DATA.filter((g) => !keep.includes(g));

// /data and every /api/admin/* route are loopback-only (src/lib/localAdmin.mjs
// refuses outright when VERCEL is set), so their deployed bundles answer 404
// and never open a data file. /api/suggest only writes to the proposals branch.
// '/api/admin' covers all four admin routes by containment. Spelling out
// '/api/admin/proposals/[id]' would not: picomatch reads [id] as a character
// class, so the literal bracketed segment never matches its own name.
const NO_DATA_ROUTES = ['/api/data-status', '/api/admin', '/api/suggest'];

// Operator trains: one generic route, reading nothing but
// public/data/scraped/<source>-trains.json.
const OPERATOR_TRAIN_ROUTES = ['/api/operator-trains'];

// The legacy per-operator URLs (/api/nightjet-trains etc.) used to be five page
// files of their own, each a thin alias of /api/operator-trains — and so five
// more function bundles in every retained deployment, each carrying the same
// trains files. They are rewrites now (see rewrites() below): same URLs, same
// responses, one function.
const LEGACY_OPERATOR_TRAIN_SOURCES = ['nightjet', 'cd', 'chinese', 'italian', 'caucasus'];

const outputFileTracingExcludes = {
  // Both halves of the map payload run the same tiered resolver
  // (api/lib/resolve-payload.mjs): published artifact → scraped file store →
  // Back-on-Track on GitHub → stale artifact. Every tier but the OSM cache is
  // reachable, so only that one is dropped — the map must never blank, and
  // trimming a tier to save 2 MB is not worth removing a rung from that ladder.
  '/api/initial-data': except(DATA.published, DATA.gtfsBundle, DATA.botRaw, DATA.operatorTrains),
  '/api/route-geometry': except(DATA.published, DATA.gtfsBundle, DATA.botRaw, DATA.operatorTrains),

  // Serves the raw Back-on-Track datasets by ?type=, nothing else.
  '/api/trains': except(DATA.botRaw),

  // Reads its OSM relation cache, falling back to the Overpass API.
  '/api/osm-relation': except(DATA.osmCache),

  ...Object.fromEntries(OPERATOR_TRAIN_ROUTES.map((r) => [r, except(DATA.operatorTrains)])),
  ...Object.fromEntries(NO_DATA_ROUTES.map((r) => [r, ALL_DATA])),

  // The sitemap reads the published artifact and the raw stops (for the
  // station → country derivation behind the country hubs). It keeps the
  // per-source trains too: src/lib/seo/stationTimes.mjs reads that whole
  // directory, and the page swallows a data-layer throw to stay HTTP 200 —
  // so a missing file would silently ship a shorter sitemap rather than fail.
  '/sitemap.xml': except(DATA.published, DATA.botRaw, DATA.operatorTrains),
};

/** @type {import('next').NextConfig} */

const nextConfig = {
  reactStrictMode: true,
  // The /sitemap.xml page runs in a request-time serverless function and reads the
  // committed data via fs (src/lib/seo/data.js). Next's file tracer can't follow that
  // dynamic read, so force these JSON files into the sitemap lambda — otherwise the
  // read throws ENOENT in production (works locally only because cwd is the repo root).
  outputFileTracingIncludes: {
    '/sitemap.xml': [
      './public/data/published/initial-data.json',
      './public/data/scraped/backontrack-stops.json',
    ],
  },
  // Per-route bundle trimming — see the DATA table above for why this is needed
  // and why it cannot be expressed as a single wildcard rule.
  outputFileTracingExcludes,
  async headers() {
    return [
      {
        // Parameterised plans are an unbounded URL space and their content
        // lives on the /connections pages they link to. They are served the
        // static /plan HTML (see rewrites below), whose <head> is the indexable
        // landing page's until the client takes over — so the noindex is sent
        // as a header, where it holds before any JavaScript runs.
        source: "/plan/:path+",
        headers: [{ key: "X-Robots-Tag", value: "noindex, follow" }],
      },
      {
        // The committed data assets: GTFS bundles and the pre-computed route
        // polylines, together several MB. Vercel serves public/ with
        // `max-age=0, must-revalidate`, so each one cost a revalidation round
        // trip on every load — expensive on a high-latency link, and pure
        // waste for files the nightly scrape rewrites at most once a day.
        //
        // `:path+` (one or more segments) rather than `:path*`, so this cannot
        // match /data itself — that is the loopback-only admin dashboard,
        // which must never be cached.
        source: "/data/:path+",
        headers: [
          {
            key: "Cache-Control",
            value:
              "public, max-age=3600, s-maxage=86400, stale-while-revalidate=604800",
          },
        ],
      },
    ];
  },
  // Every plan URL is the one static /plan page; the plan is read off the URL
  // in the browser. This used to be an ISR route, which wrote a cache entry
  // per distinct URL and put the project on course to exhaust Vercel Hobby's
  // ISR Writes quota (a hard pause, not a bill). A rewrite to a static page
  // costs no function invocation and no cache write, whatever the URL.
  async rewrites() {
    return [
      { source: "/plan/:path+", destination: "/plan" },
      ...LEGACY_OPERATOR_TRAIN_SOURCES.map((id) => ({
        source: `/api/${id}-trains`,
        destination: `/api/operator-trains?source=${id}`,
      })),
    ];
  },
  async redirects() {
    return [
      // 1. Retired URLs → their canonical page. Listed FIRST and with an absolute
      //    destination in production, so a request to the legacy host lands on the
      //    final URL in one hop instead of chaining through rule 3.
      //    301 rather than Next's `permanent: true` (which emits 308) to match what
      //    every SEO tool and the migration plan expect.
      ...Object.entries(SEO_REDIRECTS).map(([source, destination]) => ({
        source,
        destination: dest(destination),
        statusCode: 301,
      })),

      // 2. Safety net: /trains/* is retired wholesale. Anything the explicit map
      //    missed (a slug dropped from the dataset before the map was seeded, a
      //    trailing-slash variant) lands on the connections index rather than 404.
      {
        source: '/trains/:slug*',
        destination: dest('/connections'),
        statusCode: 301,
      },

      // 3. Everything else still arriving at the old host, path preserved.
      {
        source: '/:path*',
        has: [{ type: 'host', value: LEGACY_HOST }],
        destination: `${SITE_ORIGIN}/:path*`,
        statusCode: 301,
      },
    ];
  },
  webpack: (config) => {
    config.plugins.push(
      new CopyPlugin({
        patterns: [
          {
            from: 'node_modules/leaflet/dist/images',
            to: path.resolve(__dirname, 'public', 'leaflet', 'images')
          },
        ],
      }),
    )
    return config
  }
}

module.exports = nextConfig;
